on conflict (capability_key) do update set capability_name=excluded.capability_name,domain=excluded.domain,criticality=excluded.criticality,system_of_record=excluded.system_of_record,description=excluded.description,updated_at=now();

do $$ declare t text; begin foreach t in array array['platform_capability_registry','platform_event_outbox','mobile_app_installations','mobile_push_tokens','public_competition_subscriptions','mobile_release_channels','mobile_live_event_bookmarks','mobile_delivery_receipts','calendar_event_participants','calendar_event_changes','registration_requirements','registration_requirement_status','eligibility_decisions','volunteer_roles','volunteer_assignments','volunteer_credentials','document_acknowledgements','governing_body_data_sources','athlete_rankings','integration_endpoints','integration_sync_runs','competition_hardware_connections','notification_preferences','platform_authority_grants','communication_safeguarding_policies','communication_guardian_links','communication_moderation_events','finance_reconciliation_runs','finance_reconciliation_items','accounting_exports','accounting_mappings'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
update public.platform_capability_registry set status='schema_ready',updated_at=now() where capability_key <> 'coach_decision_engine';
